import{_ as a,o as t,c as n,a3 as r}from"./chunks/framework.BlfGB29P.js";const i="/eep/ini-edit-translate-2026/editor-v2-1-37-en.png",o="/eep/ini-edit-translate-2026/info-trans-v2-1-37-en.png",s="/eep/ini-edit-translate-2026/dictionary-v2-1-37-en.png",m=JSON.parse('{"title":"INI Edit Translate 2026","description":"Features of the Windows editor for EEP model INI files and Installation.eep with ChatGPT translation.","frontmatter":{"title":"INI Edit Translate 2026","description":"Features of the Windows editor for EEP model INI files and Installation.eep with ChatGPT translation."},"headers":[],"relativePath":"en/eep/ini-edit-translate-2026/index.md","filePath":"en/eep/ini-edit-translate-2026/index.md","lastUpdated":1792778683000}'),d={name:"en/eep/ini-edit-translate-2026/index.md"};function l(c,e,p,h,u,g){return t(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="ini-edit-translate-2026" tabindex="-1">INI Edit Translate 2026 <a class="header-anchor" href="#ini-edit-translate-2026" aria-label="Permalink to &quot;INI Edit Translate 2026&quot;">​</a></h1><p><strong>Version 2.1.37.0 · Windows 11 · .NET Framework 4.8</strong></p><p>Edit EEP model descriptions and installation files. Developed by Uwe Grimm / UGSo Software and published under the MIT licence.</p><p><a href="https://github.com/rockbaer2007/ini-edit-translate-2026" target="_blank" rel="noreferrer">Source code and README on GitHub</a></p><p><img src="'+i+'" alt="Version 2.1.37 design with Lime menu bar and no personal data"></p><h2 id="download" tabindex="-1">Download <a class="header-anchor" href="#download" aria-label="Permalink to &quot;Download&quot;">​</a></h2><p><a href="https://github.com/rockbaer2007/ini-edit-translate-2026/releases/download/v2.1.37/INI-Edit-Translate-2026-v2.1.37-windows.zip" target="_blank" rel="noreferrer">Download Windows ZIP v2.1.37</a> · <a href="https://github.com/rockbaer2007/ini-edit-translate-2026/releases/tag/v2.1.37" target="_blank" rel="noreferrer">GitHub release and SHA-256</a></p><p>Extract the complete ZIP and run <code>INI Edit Translate 2026.exe</code>. Requires Windows 11 and .NET Framework 4.8. Keep DLLs and language folders together. Visual Studio is only needed to build from source. No installer is required.</p><h2 id="features" tabindex="-1">Features <a class="header-anchor" href="#features" aria-label="Permalink to &quot;Features&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Area</th><th>Capabilities</th></tr></thead><tbody><tr><td>Model texts</td><td>Edit names and descriptions in EN/DE/FR/PL</td></tr><tr><td>Metadata</td><td>Edit PDF references, generation, deployment years, country and icon</td></tr><tr><td>Movement axes and signal functions</td><td>Display, edit and translate language-specific entries</td></tr><tr><td>Installation.eep</td><td>Edit names and descriptions of supported installation sections</td></tr><tr><td>Preview</td><td>Compare the original file with the generated output preview</td></tr><tr><td>Table export</td><td>Export complete tables as tab-separated UTF-8 files with a BOM</td></tr><tr><td>Backups</td><td>Copy existing INI files before overwriting them, retaining their original filename</td></tr></tbody></table><h2 id="chatgpt-translation" tabindex="-1">ChatGPT translation <a class="header-anchor" href="#chatgpt-translation" aria-label="Permalink to &quot;ChatGPT translation&quot;">​</a></h2><p>The application uses only the OpenAI Responses API. Each source text is translated into the three other target languages in one request, without an English intermediate translation. Repeated texts share a temporary cache within the same operation.</p><p>The progress dialog provides <strong>Cancel</strong>. The request timeout is 60 seconds; each text is limited to 24,000 characters. Incomplete responses, missing languages and changed placeholders such as <code>{0}</code>, <code>%s</code> or <code>[e]</code> are rejected. Existing texts and tables are preserved on failure.</p><p>DE/EN/FR interface texts have been reviewed for broken characters, wrong-language entries and mixed messages. Technical INI keys such as <code>Name_GER</code> are retained.</p><h2 id="setup-and-workflow" tabindex="-1">Setup and workflow <a class="header-anchor" href="#setup-and-workflow" aria-label="Permalink to &quot;Setup and workflow&quot;">​</a></h2><ol><li>Download the Windows ZIP above and extract all files.</li><li>Start <code>INI Edit Translate 2026.exe</code> from the extracted directory, keeping its DLLs and language directories together.</li><li>Open <strong>About → Settings → OpenAI translation</strong>. Enter your own API key and model; the default is <code>gpt-4.1-mini</code>.</li><li>Open a backed-up file in <strong>Read only</strong> mode first.</li><li>Use <strong>Read and translate</strong> or a translation button. Select the source language for axes and signal functions.</li><li>Review the preview and model texts, then save explicitly.</li></ol><p>The information dialog selects the reviewed <code>Info.de.rtf</code>, <code>Info.en.rtf</code> or <code>Info.fr.rtf</code> to match the interface language. The historical <code>Info.rtf</code> is retained unchanged. Current help describes OpenAI translation and the restored reference program.</p><h2 id="github-updates" tabindex="-1">GitHub updates <a class="header-anchor" href="#github-updates" aria-label="Permalink to &quot;GitHub updates&quot;">​</a></h2><p>Choose <strong>About → Check for updates</strong> to query the latest public GitHub release. There is no automatic startup check. Only a newer stable version is offered, with its version number and release notes.</p><p><strong>Download and install</strong> downloads the Windows ZIP and SHA-256 checksum. Download and package validation can be cancelled and finish before the application closes. Save open files and close Info_trans before installation. Installation requires confirmation. A separate helper waits for the editor to exit, backs up existing files and installs the package.</p><p>Settings and the encrypted OpenAI key are retained. Existing reference-help FDB, CSV, DAT and configuration files, plus the original Info.rtf, are backed up and not replaced. Your model files are left intact. On installation failure, the updater attempts to restore files already replaced and records the result. Backups and reports are stored under <code>%LOCALAPPDATA%/UGSo/IET2026/updates/&lt;identifier&gt;/</code>.</p><p>No server credentials are needed. Checksums verify integrity; no additional digital package signature is implemented. 32 isolated update checks cover downloads, cancellation, package paths, retained data, locked files and rollback after partial writes.</p><h2 id="second-program-info-trans" tabindex="-1">Second program: Info_trans <a class="header-anchor" href="#second-program-info-trans" aria-label="Permalink to &quot;Second program: Info_trans&quot;">​</a></h2><p>The package also includes <code>help/Info_trans.exe</code>. <strong>Reference help</strong> in the main editor opens it in the selected language. The actual <code>IET2.FDB</code> and its native Firebird 2.5.8 runtime were restored from the 2019 archive. No separate Firebird server installation is required.</p><p>The database contains 5 building entries, 2 goods entries and 2 update entries. Signals, rolling stock, track objects and landscape tables are empty in the original. Also included: 236 icon entries, 369 technical terms and 2,428 reviewed entries in the <strong>DE/EN/FR dictionary</strong>. English is the reference; confirmed German corrections and French translations are included. Continuation rows were merged and mixed terms were separated. American and British terminology retains its original labels. All dictionary review questions are resolved. The original DE/EN file and source database remain unchanged in the complete package.</p><p><img src="'+o+'" alt="Info_trans 2.1.37 with Lime tabs and the loaded original database"></p><p><img src="'+s+'" alt="Three-language Info_trans dictionary with readable German, English and French columns"></p><p><code>Info_trans</code> is built for x86 to match the native DLLs. The managed provider FirebirdSql.Data.FirebirdClient 7.5.0.0 was verified with the real Firebird 2.5.8 database. Tests read separate database copies and compare all seven tables with the DE/EN/FR interface. Packaging includes the unchanged source database.</p><p>Missing or unloadable components are reported and SQL import is then disabled. A local database backup precedes an available manual SQL import. Automatic application updates remain disabled.</p><h2 id="data-and-privacy" tabindex="-1">Data and privacy <a class="header-anchor" href="#data-and-privacy" aria-label="Permalink to &quot;Data and privacy&quot;">​</a></h2><p>Old registrations and personal databases are not imported. Settings are stored separately for each Windows user. OpenAI configuration and file backups are under <code>%LOCALAPPDATA%/UGSo/IET2026/</code>.</p><p>Windows DPAPI encrypts the API key for the current Windows account. Selected texts are sent to OpenAI with <code>store: false</code>. Internet access and separate API billing are required; a ChatGPT subscription does not replace API billing.</p><h2 id="updates-and-verification" tabindex="-1">Updates and verification <a class="header-anchor" href="#updates-and-verification" aria-label="Permalink to &quot;Updates and verification&quot;">​</a></h2><p><strong>GitHub updates are started manually and require installation confirmation.</strong> The old update server is not used. Google, LEO, Linguee and DeepL are no longer offered.</p><p>41 local checks with mocked API responses and Debug/Release builds cover failures, cancellation, restoration, export and rendered DE/EN/FR interfaces. Tests do not send texts to OpenAI. A live API request and generated translation quality still need verification with your own account. Not every possible INI schema is supported; review the resulting model data before use.</p><p>The user reviewed the complete local 2.1.37 release and confirmed it works before publication. The ZIP includes both programs, the native Firebird runtime, original database and corrected dictionary. ZIP integrity and SHA-256 were verified; all seven database tables were compared with the DE/EN/FR interface using separate copies. Screenshots show the current design with neutral data and no private settings.</p>',36)])])}const b=a(d,[["render",l]]);export{m as __pageData,b as default};
